      readbackMode,
      gpuFenceRequirement: gpuFence,
      gpuResidentLane,
      lawGraphNode,
      pressureInterfaceSourceKeyReplayDescriptor,
      portableReplayInputDescriptors,
      computeTaskSchema: ULG_SPH_PRESSURE_INTERFACE_STAGE_COMPUTE_TASK_SCHEMA,
      computeTaskId: id,
