    thermalMechanicsRefreshStatus,
    ...thermalPhaseTransition,
    thermalPhaseTransitionCouplingStatus,
    residentBufferMode: residentBuffersRetained ? 'retained-stage-and-output-buffers' : 'cpu-artifact-fallback',
